const userByToken = `-- name: UserByToken :one
SELECT u.id, u.email, u.name, u.is_instance_admin
FROM users u JOIN api_tokens t ON t.user_id = u.id
WHERE t.token_hash = $1
`

type UserByTokenRow struct {
	ID              int64
	Email           string
	Name            string
	IsInstanceAdmin bool
}

func (q *Queries) UserByToken(ctx context.Context, tokenHash string) (UserByTokenRow, error) {
	row := q.db.QueryRow(ctx, userByToken, tokenHash)
	var i UserByTokenRow
	err := row.Scan(
		&i.ID,
		&i.Email,
		&i.Name,
		&i.IsInstanceAdmin,
	)
	return i, err
}

